//! Golden tests: expected values from the reference tmux 3.8, generated by
//! `tests/options_cases.sh` into `golden/`. That script's header says which
//! reference command produced each file and pins the environment
//! (`SHELL=/bin/sh`, no `EDITOR`/`VISUAL`, `HOME=/home/vtmux-test`) that
//! [`Defaults::default`] and [`Env`] mirror here.

use std::collections::HashMap;

use super::{Defaults, OptionHost, OptionsStore, SetOutcome, Target, apply_set, apply_show, table};
use crate::cmd::{
    ArgValue, CommandCall, CommandList, ConfigEnv, ParseOpts, parse_argv, parse_config_with,
    parse_string,
};
use crate::format::{self, FormatContext};
use crate::ids::{PaneId, SessionId, WindowId};

const DEFAULTS: &str = include_str!("golden/defaults.txt");
const LISTINGS: &str = include_str!("golden/listings.txt");
const CASES: &str = include_str!("golden/cases.txt");
const ENV: &str = include_str!("golden/env.txt");
const OWNER_TMUX_CONF: &str = include_str!("golden/owner_tmux.conf");
const OWNER_TMUX: &str = include_str!("golden/owner_tmux.txt");
const OWNER_MU_CREW_CONF: &str = include_str!("golden/owner_mu-crew.conf");
const OWNER_MU_CREW: &str = include_str!("golden/owner_mu-crew.txt");

/// `HOME` in the reference run.
const HOME: &str = "/home/vtmux-test";
/// Where the script puts the owner's config copies (`#{current_file}`).
const OWNER_DIR: &str = "/tmp/vtmux-options-golden";

/// The reference server: session `s` ($0) with window @0 and pane %0.
const SESSION: SessionId = SessionId(0);
const WINDOW: WindowId = WindowId(0);
const PANE: PaneId = PaneId(0);

/// The reference's global environment, as far as the cases read it.
struct Env(HashMap<String, String>);

impl ConfigEnv for Env {
    fn var(&self, name: &str) -> Option<String> {
        self.0.get(name).cloned()
    }
    fn home(&self, user: Option<&str>) -> Option<String> {
        user.is_none().then(|| HOME.to_owned())
    }
    fn set(&mut self, name: &str, value: &str, _hidden: bool) {
        self.0.insert(name.to_owned(), value.to_owned());
    }
    /// The cases' `%if` conditions read no option: the reference expands
    /// them before any `set` in the file has run.
    fn expand(&self, template: &str) -> String {
        format::expand_str(
            template,
            &Vars {
                store: &OptionsStore::new(&Defaults::default()),
                target: Target::default(),
                extra: &[],
            },
        )
    }
}

/// Format variables: the extras `show -F` adds, then options
/// (`format_find` looks at options first, but no option is called
/// `option_*` or `current_file`).
struct Vars<'a> {
    store: &'a OptionsStore,
    target: Target,
    extra: &'a [(&'a str, String)],
}

impl FormatContext for Vars<'_> {
    fn get(&self, name: &str) -> Option<String> {
        if let Some((_, v)) = self.extra.iter().find(|(k, _)| *k == name) {
            return Some(v.clone());
        }
        self.store.format_value(name, &self.target)
    }
}

struct Host {
    env: Env,
    target: Target,
    current_file: Option<String>,
}

impl OptionHost for Host {
    fn expand(&mut self, store: &OptionsStore, template: &str, extra: &[(&str, String)]) -> String {
        let mut all: Vec<(&str, String)> = extra.to_vec();
        if let Some(f) = &self.current_file {
            all.push(("current_file", f.clone()));
        }
        format::expand_str(
            template,
            &Vars {
                store,
                target: self.target,
                extra: &all,
            },
        )
    }
    fn config_env(&mut self) -> &mut dyn ConfigEnv {
        &mut self.env
    }
    fn usable_shell(&self, path: &str) -> bool {
        path.starts_with('/') && std::path::Path::new(path).is_file()
    }
}

/// A server's options plus what ran against it printed.
struct Sim {
    store: OptionsStore,
    host: Host,
    out: String,
}

impl Sim {
    fn new() -> Self {
        let mut store = OptionsStore::new(&Defaults::default());
        store.add_session(SESSION);
        store.add_window(WINDOW);
        store.add_pane(PANE, WINDOW);
        Self {
            store,
            host: Host {
                env: Env(HashMap::from([("HOME".to_owned(), HOME.to_owned())])),
                target: Target::default(),
                current_file: None,
            },
            out: String::new(),
        }
    }

    fn say(&mut self, line: &str) {
        self.out.push_str(line);
        self.out.push('\n');
    }

    /// `cmd_find_target` with `CMD_FIND_CANFAIL` for the cases' targets.
    fn target(call: &CommandCall) -> Target {
        let all = Target {
            session: Some(SESSION),
            window: Some(WINDOW),
            pane: Some(PANE),
        };
        match call.args.value('t') {
            None | Some("s" | "s:0" | "%0" | "@0" | "$0") => all,
            Some(_) => Target::default(),
        }
    }

    /// Run commands the way the queue does: a command that fails ends the
    /// rest of its group. Returns false if one failed.
    fn run(&mut self, calls: &[CommandCall]) -> bool {
        let mut ok = true;
        let mut failed_group = None;
        for call in calls {
            if failed_group == Some(call.group) {
                continue;
            }
            if let Err(e) = self.run_one(call) {
                self.say(&e);
                failed_group = Some(call.group);
                ok = false;
            }
        }
        ok
    }

    fn run_one(&mut self, call: &CommandCall) -> Result<(), String> {
        self.host.target = Self::target(call);
        let target = self.host.target;
        match call.entry.name {
            "set-option" | "set-window-option" | "set-hook" => {
                apply_set(&mut self.store, call, &target, &mut self.host)
                    .map(|_: SetOutcome| ())
                    .map_err(|e| e.to_string())
            }
            "show-options" | "show-window-options" | "show-hooks" => {
                let lines = apply_show(&self.store, call, &target, &mut self.host)
                    .map_err(|e| e.to_string())?;
                for l in lines {
                    self.say(&l);
                }
                Ok(())
            }
            "if-shell" if call.args.flag('F') => {
                // cmd-if-shell.c with -F: the format decides, no shell.
                let cond = call.args.positional_text(0).unwrap_or_default();
                let cond = self.host.expand(&self.store, &cond, &[]);
                let branch = if !cond.is_empty() && cond != "0" {
                    1
                } else {
                    2
                };
                let list = match call.args.positionals.get(branch) {
                    None => return Ok(()),
                    Some(ArgValue::Commands(list)) => list.clone(),
                    Some(ArgValue::Str(text)) => {
                        parse_string(text, &mut self.host.env).map_err(|e| e.to_string())?
                    }
                };
                let CommandList { calls } = list;
                if self.run(&calls) {
                    Ok(())
                } else {
                    Err(String::new())
                }
            }
            // Key bindings and the environment are other modules' state.
            "bind-key" | "unbind-key" | "set-environment" => Ok(()),
            other => panic!("the cases do not run {other}"),
        }
    }

    /// One `tmux ARGS...` invocation.
    fn argv(&mut self, words: &[&str]) {
        let words: Vec<String> = words.iter().map(|w| (*w).to_owned()).collect();
        match parse_argv(&words) {
            Ok(calls) => {
                self.run(&calls);
            }
            Err(e) => self.say(&e.to_string()),
        }
    }

    /// `source-file` of `text` at `path`.
    fn source(&mut self, path: &str, text: &str) {
        self.host.current_file = Some(path.to_owned());
        match parse_config_with(text, &mut self.host.env, ParseOpts::default()) {
            Ok(calls) => {
                self.run(&calls);
            }
            Err(e) => self.say(&format!("! {e}")),
        }
        self.host.current_file = None;
    }

    fn take(&mut self) -> String {
        std::mem::take(&mut self.out)
    }
}

/// `### name`, `$ args` lines (0x1f-separated), output lines, `%%`.
fn cases(text: &str) -> Vec<(&str, Vec<Vec<&str>>, String)> {
    let mut out = Vec::new();
    let mut lines = text.split('\n');
    while let Some(line) = lines.next() {
        let Some(name) = line.strip_prefix("### ") else {
            continue;
        };
        let mut commands = Vec::new();
        let mut expected = String::new();
        for l in lines.by_ref() {
            if l == "%%" {
                break;
            }
            match l.strip_prefix("$ ") {
                Some(cmd) if expected.is_empty() => commands.push(cmd.split('\x1f').collect()),
                _ => {
                    expected.push_str(l);
                    expected.push('\n');
                }
            }
        }
        out.push((name, commands, expected));
    }
    out
}

fn run_cases(text: &str, min: usize) {
    let all = cases(text);
    assert!(all.len() >= min, "{} cases", all.len());
    let mut failures = Vec::new();
    for (name, commands, expected) in all {
        let mut sim = Sim::new();
        for c in &commands {
            sim.argv(c);
        }
        let got = sim.take();
        if got != expected {
            failures.push(format!("### {name}\n{}", diff(&expected, &got)));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The first differing line of two outputs, with context.
fn diff(expected: &str, got: &str) -> String {
    let e: Vec<&str> = expected.lines().collect();
    let g: Vec<&str> = got.lines().collect();
    let at = e
        .iter()
        .zip(&g)
        .position(|(a, b)| a != b)
        .unwrap_or(e.len().min(g.len()));
    format!(
        "line {}: expected {:?}\n        got      {:?}\n({} vs {} lines)",
        at + 1,
        e.get(at),
        g.get(at),
        e.len(),
        g.len()
    )
}

/// `show -g NAME` for every option in the table, on a fresh server.
#[test]
fn options_defaults_match_reference() {
    let mut failures = Vec::new();
    let mut rows = 0;
    for line in DEFAULTS.lines() {
        let (name, expected) = line.split_once('\t').expect("a tab");
        rows += 1;
        let mut sim = Sim::new();
        sim.argv(&["show", "-g", name]);
        let got = sim.take().trim_end_matches('\n').replace('\n', "\x1e");
        if got != expected {
            failures.push(format!("{name}: expected {expected:?}\n   got {got:?}"));
        }
    }
    assert_eq!(rows, table().len());
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Whole-tree listings (`show -s`, `-gH`, `show-hooks`, `-A`, `-v`, `-F`).
#[test]
fn options_listings_match_reference() {
    run_cases(LISTINGS, 19);
}

/// set/show round trips for every type, error texts, arrays, hooks, user
/// options, -o -u -U -F -q -a, scopes and inheritance.
#[test]
fn options_set_show_match_reference() {
    run_cases(CASES, 50);
}

/// The environment's part of the defaults (tmux.c:540-553).
#[test]
fn options_env_defaults_match_reference() {
    let opt = |v: &str| (v != "-").then(|| v.to_owned());
    for line in ENV.lines() {
        let mut f = line.split('\t');
        let (visual, editor, expected) = (f.next().unwrap(), f.next().unwrap(), f.next().unwrap());
        let defaults = Defaults::from_env("/bin/sh".to_owned(), opt(visual), opt(editor));
        let store = OptionsStore::new(&defaults);
        let mut sim = Sim::new();
        sim.store = store;
        for name in ["editor", "status-keys", "mode-keys"] {
            sim.argv(&["show", "-gv", name]);
        }
        let got = sim.take().trim_end().replace('\n', "|");
        assert_eq!(got, expected, "VISUAL={visual} EDITOR={editor}");
    }
}

/// No pending format modifiers: `s/.../.../` is evaluated by `fmt_regex`.
const PENDING_FORMAT_MODIFIERS: &[&str] = &[];

/// The owner's two configs (shell commands and `source-file` removed),
/// applied in order, then every server, session and window option listed.
fn owner_config(file: &str, conf: &str, expected: &str) {
    let mut sim = Sim::new();
    sim.source(&format!("{OWNER_DIR}/{file}"), conf);
    for flags in ["-sH", "-gH", "-gwH"] {
        sim.argv(&["show", flags]);
    }
    let got = sim.take();
    let name_of = |l: &str| l.split([' ', '[']).next().unwrap_or_default().to_owned();
    let pending = |l: &&str| PENDING_FORMAT_MODIFIERS.contains(&name_of(l).as_str());
    let keep = |s: &str| {
        s.lines()
            .filter(|l| !pending(l))
            .collect::<Vec<_>>()
            .join("\n")
    };
    assert_eq!(keep(&got), keep(expected), "{file}");
    for name in PENDING_FORMAT_MODIFIERS {
        let mine: Vec<&str> = got.lines().filter(|l| name_of(l) == *name).collect();
        let theirs: Vec<&str> = expected.lines().filter(|l| name_of(l) == *name).collect();
        if !theirs.is_empty() {
            assert_ne!(
                mine, theirs,
                "{name} now matches: remove it from the pending list"
            );
        }
    }
}

#[test]
fn options_owner_tmux_conf_matches_reference() {
    owner_config("tmux.conf", OWNER_TMUX_CONF, OWNER_TMUX);
}

#[test]
fn options_owner_mu_crew_conf_matches_reference() {
    owner_config("mu-crew.conf", OWNER_MU_CREW_CONF, OWNER_MU_CREW);
}

/// The FACTS in the brief, spelled out so a regenerated golden file cannot
/// quietly change them.
#[test]
fn options_facts() {
    let mut sim = Sim::new();
    for c in [
        &["set", "-g", "history-limit", "x"][..],
        &["set", "-g", "mouse", "maybe"],
        &["set", "-g", "status-fg", "x"],
        &["set", "-g", "display-panes-colour", "x"],
        &["set", "-g", "status-style", "fg=x"],
        &["set", "-g", "prefix", "Foo"],
        &["set", "-g", "prefix", "^B"],
        &["show", "-g", "prefix"],
        &[
            "set",
            "-g",
            "default-client-command",
            "new;  neww -n \"x y\"",
        ],
        &["show", "-g", "default-client-command"],
    ] {
        sim.argv(c);
    }
    assert_eq!(
        sim.take(),
        "value is invalid: x\nbad value: maybe\nbad colour: x\ninvalid colour: x\n\
         invalid style: fg=x\nbad key: Foo\nprefix C-b\n\
         default-client-command new-session ; new-window -n \"x y\"\n"
    );
}

/// vtmux options (D23) are invisible until set: named lookups print the
/// default, listings (with or without `-A`) leave them out, prefixes stay
/// tmux's errors; once set at a scope they are listed there, and `-u`
/// hides them again.
#[test]
fn vtmux_options_hidden_until_set() {
    let listing = |sim: &mut Sim, args: &[&str]| {
        sim.argv(args);
        sim.take()
    };
    let mut sim = Sim::new();
    let fresh: Vec<String> = [&["show", "-gw"][..], &["show", "-wA"], &["show", "-g"]]
        .iter()
        .map(|a| listing(&mut sim, a))
        .collect();
    assert!(fresh.iter().all(|l| !l.contains("vtmux")));
    for c in [
        &["show", "-gv", "vtmux-focus-ring"][..],
        &["show", "-gw", "vtmux-focus-ring"],
        &["show", "-w", "vtmux-focus-ring"],
        &["show", "-wA", "vtmux-focus-ring"],
        &["show", "-gA", "vtmux-focus-ring"],
        &["show", "-gwA", "vtmux-focus-ring"],
        &["set", "-g", "vt", "on"],
        &["show", "-g", "vtm"],
        &["set", "-g", "vtmux-focus-ring", "bogus"],
    ] {
        sim.argv(c);
    }
    assert_eq!(
        sim.take(),
        "off\nvtmux-focus-ring off\nvtmux-focus-ring* off\n\
         vtmux-focus-ring off\nvtmux-focus-ring off\n\
         invalid option: vt\ninvalid option: vtm\nbad value: bogus\n"
    );
    sim.argv(&["set", "-gw", "vtmux-focus-ring", "on"]);
    let set = listing(&mut sim, &["show", "-gw"]);
    assert!(
        set.ends_with("xterm-keys on\nvtmux-focus-ring on\n"),
        "{set}"
    );
    assert_eq!(
        listing(&mut sim, &["show", "-wA"]).lines().last(),
        Some("vtmux-focus-ring* on")
    );
    assert!(!listing(&mut sim, &["show", "-w"]).contains("vtmux"));
    sim.argv(&["set", "-w", "vtmux-focus-ring", "off"]);
    assert_eq!(listing(&mut sim, &["show", "-w"]), "vtmux-focus-ring off\n");
    sim.argv(&["set", "-gwu", "vtmux-focus-ring"]);
    sim.argv(&["set", "-wu", "vtmux-focus-ring"]);
    assert_eq!(listing(&mut sim, &["show", "-gw"]), fresh[0]);
    assert_eq!(
        listing(&mut sim, &["show", "-gv", "vtmux-focus-ring"]),
        "off\n"
    );
}
